package com.orderflow.notification.controller;import com.orderflow.notification.domain.NotificationType;import com.orderflow.notification.dto.*;import com.orderflow.notification.service.*;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/notifications")public class NotificationController{private final NotificationQueryService query;private final PreferenceService preferences;private final SseRegistry streams;public NotificationController(NotificationQueryService q,PreferenceService p,SseRegistry s){query=q;preferences=p;streams=s;}private UUID user(JwtAuthenticationToken a){return UUID.fromString(a.getToken().getSubject());}@GetMapping public PageResponse<NotificationResponse>list(JwtAuthenticationToken a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)Boolean read,@RequestParam(required=false)NotificationType type,@RequestParam(defaultValue="desc")String sort){return query.list(user(a),page,size,read,type,sort);}@GetMapping("/unread-count")public UnreadCountResponse unread(JwtAuthenticationToken a){return new UnreadCountResponse(query.unread(user(a)));}@PatchMapping("/{id}/read")public NotificationResponse read(@PathVariable UUID id,JwtAuthenticationToken a){return query.read(user(a),id);}@PatchMapping("/read-all")public UnreadCountResponse readAll(JwtAuthenticationToken a){query.readAll(user(a));return new UnreadCountResponse(query.unread(user(a)));}@GetMapping("/preferences")public PreferenceResponse preference(JwtAuthenticationToken a){return preferences.get(user(a));}@PutMapping("/preferences")public PreferenceResponse preference(@Valid @RequestBody PreferenceRequest b,JwtAuthenticationToken a){return preferences.update(user(a),b);}@GetMapping("/stream")public SseEmitter stream(JwtAuthenticationToken a){return streams.connect(user(a));}}
